export type Moment = {
	kind: MomentKind,
	/**  Seconds from the start of the clip. */
	start: number | null,
	end: number | null,
	/**  0..1. Coarse logs score lower; see `detail`. */
	score: number | null,
	source: Source,
	/**  One line on what was seen. */
	detail: string,
};

export type MomentKind = 
/**  Full aileron, held. */
"roll" | 
/**  Full elevator, held. */
"flip" | 
/**  Throttle from low to near full, fast. */
"punch" | 
/**  Throttle near zero for a while mid-flight, then a punch. */
"dive" | 
/**  The log segment ends right after big inputs. Low confidence. */
"crash" | 
/**  No usable picture: blue screen, static, test pattern, black. */
"dead_air";

/**  `card_status`: a card's mount point. */
export type MountParams = {
	mount: string,
};

/**  A library file in the Trash: the clip it belongs to, where it was, where it is now. */
