/**
 *  The head's values for the other state of the join: the file's own while the join is on,
 *  the whole recording's while it is off. Turning the join on or off swaps them in.
 */
export type Swap = {
	duration: number | null,
	probe: Probe | null,
	signal: SignalScan | null,
	detail: string,
};

export type SwitchWarning = {
	/**  `SA`. */
	switch: string,
	/**  `up`, `mid` or `down`. */
	pos: string,
};

/**  The long library jobs. */
export type Task = "rebuild" | "cuts" | "thumbnails" | "moments";

export type Timer = {
	/**  0 is Timer 1. */
	index: number,
	name: string,
	/**  The switch that runs it (`L1`, `NONE`). */
	swtch: string,
	mode: string,
	/**  The stored count, in seconds. */
	value: number,
	/**  0 off, 1 per flight, 2 until a manual reset. */
	persistent: string,
	/**  Every field, raw, in file order. */
	fields: Field[],
};

export type Tools = {
	ffmpeg: string,
	ffprobe: string,
};

/**  Totals for the footer. */
export type Totals = {
	clips: number,
	bytes: number,
	seconds: number | null,
	flying: number | null,
};

export type TrashReport = {
	trashed: string[],
	failed: ([string, string])[],
	/**  Where each file went, so `library_untrash` can put it back. */
	moved: Moved[],
};

/**  One flight's worst link, for the range trend. */
export type TrendPoint = {
	flight: string,
	start: string,
	worst_lq: number | null,
	worst_rssi_db: number | null,
};

export type Tunables = {
	/**  A gap over this many seconds between rows starts a new armed segment. */
	segment_gap_s: number | null,
	/**  A gap over this many minutes between segments starts a new session. */
	session_gap_min: number | null,
	/**  Slack, in seconds, allowed when a clip claims segments. */
	tolerance_s: number | null,
	/**  A log day further than this from the import date means the radio clock reset. */
	max_log_age_days: number,
	/**
	 *  A clip with its own clock (DJI) takes a matching log's time only when the log starts
	 *  within this many seconds of the clip clock.
	 */
	clock_skew_s?: number | null,
};

/**  `library_untrash`: the files `library_trash` moved. */
export type UntrashParams = {
	moved: Moved[],
};

/**  What a USB device says about itself. */
export type UsbInfo = {
	vid: number,
	pid: number,
	vendor?: string | null,
	product?: string | null,
	/**  The USB serial number. EdgeTX radios report a generic one, so it is not an id. */
	serial?: string | null,
	/**  `bcdDevice` as `major.minor` (an EdgeTX radio reports its firmware's, `2.12`). */
	version?: string | null,
};

/**  One FC's USB heat timer. It runs while the FC is on USB with its battery in. */
export type UsbTimer = {
	port: string,
	id: string | null,
	/**  A battery is in (the FC reads more than 1 V on its battery lead). */
	battery: boolean,
	volts: number | null,
	/**  Seconds on USB with the battery in. */
	elapsed_s: number,
	/**  The limit in seconds; None when the timer is off (`gearUsbMinutes` 0). */
	limit_s: number | null,
	/**  Seconds left; 0 once past the limit. */
	remaining_s: number | null,
	/**  "Unplug now" played for this battery session. */
	warned: boolean,
};

/**  `verify`: the clips to check again (all verified clips when None). */
export type VerifyParams = {
	ids: number[] | null,
};

export type VerifyReport = {
	id: number,
	output: string,
	ok: boolean,
	error: string | null,
};

/**  What speaks the cue lines. */
export type VoiceSource = "macos" | "voice_pack";

/**  A mounted volume the app may care about. */
export type Volume = {
	mount: string,
	info: DiskInfo,
	/**  Removable and holds clips of a source QuadCam reads. */
	is_card: boolean,
	/**  The video system of the clips on a card. */
	source?: SourceKind | null,
	/**  Holds `LOGS/` next to `MODELS/` or `RADIO/`: an EdgeTX radio in USB Storage mode. */
	is_radio: boolean,
	warnings: string[],
};

/**  Something mounted or unmounted under /Volumes. */
export type VolumesChanged = null;

/**  The worst link of the session. */
export type WorstLink = {
	flight: string,
	start: string,
	lq: number | null,
	rssi_db: number | null,
};

/* Tauri Specta runtime */
async function typedError<T, E>(result: Promise<T>): Promise<{ status: "ok"; data: T } | { status: "error"; error: E }> {
    try {
        return { status: "ok", data: await result };
    } catch (e) {
        if (e instanceof Error) throw e;
        return { status: "error", error: e as any };
    }
}

type EventEmit<T> = [T] extends [null] ? () => Promise<void> : (payload: T) => Promise<void>;

function makeEvent<T>(name: string, serialize?: (payload: T) => unknown, deserialize?: (payload: any) => T) {
    const mapEvent = (cb: __TAURI_EVENT.EventCallback<T>) => (event: __TAURI_EVENT.Event<any>) => cb({ ...event, payload: deserialize ? deserialize(event.payload) : event.payload });
    const mapPayload = (payload: T) => serialize ? serialize(payload) : payload;

    const base = {
        listen: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.once(name, mapEvent(cb)),
        emit: ((payload: T) => __TAURI_EVENT.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>
    };

    const fn = (target: import("@tauri-apps/api/webview").Webview | import("@tauri-apps/api/window").Window) => ({
        listen: (cb: __TAURI_EVENT.EventCallback<T>) => target.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<T>) => target.once(name, mapEvent(cb)),
        emit: ((payload: T) => target.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>
    });

    return Object.assign(fn, base);
}

